#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> par(n);
    for (int i = 0; i < n; i++) cin >> par[i];

    vector<vector<int>> kids(n + 1);
    int root = 0;
    for (int v = 1; v <= n; v++) {
        if (par[v - 1] == 0) root = v;
        else kids[par[v - 1]].push_back(v);
    }
    long long depth = 0;
    vector<int> level = {root};
    for (;;) {
        vector<int> next;
        for (int v : level) {
            for (int c : kids[v]) next.push_back(c);
        }
        if (next.empty()) break;
        depth++;
        level = next;
    }
    cout << depth << "\n";

    return 0;
}

