import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] par = new long[(int) n];
        for (int i = 0; i < par.length; i++) par[i] = Long.parseLong(next());

        int count = (int) n;
        List<List<Integer>> kids = new ArrayList<>();
        for (int v = 0; v <= count; v++) kids.add(new ArrayList<>());
        int root = 0;
        for (int v = 1; v <= count; v++) {
            if (par[v - 1] == 0) root = v;
            else kids.get((int) par[v - 1]).add(v);
        }
        long depth = 0;
        List<Integer> level = new ArrayList<>();
        level.add(root);
        for (;;) {
            List<Integer> next = new ArrayList<>();
            for (int v : level) next.addAll(kids.get(v));
            if (next.isEmpty()) break;
            depth++;
            level = next;
        }
        System.out.println(depth);
    }
}
